import{_ as t,a,b as o,c as s,d as r}from"./chunks/cg_4.zHWnKZIH.js";import{_ as n,c as i,o as c,ae as l}from"./chunks/framework.Cd-3tpCq.js";const b=JSON.parse('{"title":"Category Feature","description":"Learn how to use the category feature in MinecraftSounds","frontmatter":{"title":"Category Feature","description":"Learn how to use the category feature in MinecraftSounds"},"headers":[],"relativePath":"en/tutorials/category.md","filePath":"en/tutorials/category.md"}'),u={name:"en/tutorials/category.md"};function d(h,e,g,p,m,_){return c(),i("div",null,e[0]||(e[0]=[l('<hr><h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>The category feature helps organize audio files conveniently. For example, when building game levels, all audio files for the first level can be placed in the Level 1 category.</p><p>The category feature button is located in the upper right corner of the audio list, as shown:<br><img src="'+t+'" alt="Category"></p><h1 id="how-to-use-categories" tabindex="-1">How to Use Categories <a class="header-anchor" href="#how-to-use-categories" aria-label="Permalink to &quot;How to Use Categories&quot;">​</a></h1><ol><li>Click the &quot;Add Category&quot; button <img src="'+a+'" alt="Add Category"></li><li>Enter the category name in the dialog box that appears <img src="'+o+'" alt="Add Category"></li></ol><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Category names cannot contain spaces or special characters. Only combinations of lowercase English characters or Arabic numerals are allowed. It&#39;s best not to have numbers at the beginning and not to use pure numbers.</p></div><ol start="3"><li>Click the &quot;OK&quot; button. When prompted with &quot;Creation successful&quot;, the category has been successfully added <img src="'+s+'" alt="Add Category"></li><li>You can switch categories in the dropdown selection box in the audio list <img src="'+r+'" alt="Switch Category"></li></ol><h1 id="changes-when-using-categories" tabindex="-1">Changes When Using Categories <a class="header-anchor" href="#changes-when-using-categories" aria-label="Permalink to &quot;Changes When Using Categories&quot;">​</a></h1><p>For version 1.7.10 and below: /playsound mcsd.{category_name}.{sound_effect_soundkey} @a ~ ~ ~ 10000 For version 1.8 and above: /playsound mcsd.{category_name}.{sound_effect_soundkey} record @a ~ ~ ~ 10000</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>When using categories, you need to replace {category_name} with the actual category name and {sound_effect_soundkey} with the actual sound effect soundkey. For example: If a category name is &quot;test&quot; and a sound effect soundkey is &quot;my_sound&quot;, then the complete soundkey would be &quot;mcsd.test.my_sound&quot;.</p></div>',11)]))}const C=n(u,[["render",d]]);export{b as __pageData,C as default};
